import json, re
from pathlib import Path

# Reimplement dapo minerva and boxed check
ANSWER_RE = re.compile(r"(?i)Answer\s*:\s*([^\n]+)")
BOXED_RE = re.compile(r"\\boxed\s*\{([^{}]*)\}")

def last_boxed(s):
    idx = s.rfind("\\boxed{")
    if idx < 0:
        # also \boxed { with space
        m = list(re.finditer(r"\\boxed\s*\{", s))
        if not m:
            return None
        idx = m[-1].start()
        # find brace
        brace = s.find("{", idx)
    else:
        brace = idx + len("\\boxed")
        # idx points at backslash, brace is after boxed
        brace = s.find("{", idx)
    if brace < 0:
        return None
    i = brace
    depth = 0
    for j in range(brace, len(s)):
        if s[j] == "{":
            depth += 1
        elif s[j] == "}":
            depth -= 1
            if depth == 0:
                return s[brace+1:j]
    return None

def norm(a):
    a = a.strip()
    a = a.replace("$","").replace(" ","")
    a = a.replace(",","")
    a = a.replace("\\text{","")
    a = a.replace("{","").replace("}","")
    a = a.replace("\\","")
    return a.strip()

def minerva_pred(text):
    tail = text[-300:]
    m = ANSWER_RE.findall(tail)
    if not m:
        return None
    return m[-1].strip()

def answers_match(pred, gts):
    if pred is None:
        return False
    np = norm(pred)
    for g in gts:
        if np == norm(g):
            return True
        # numeric
        try:
            if abs(float(np) - float(norm(g))) < 1e-6:
                return True
        except:
            pass
    return False

